/** Pick references from a paginated server search instead of downloading all garage data. */
export function Picker<K extends Kind>({ api, kind, label, value, onChange, describe }: {
  api: Api; kind: K; label: string; value: string; onChange: (id: string, text: string) => void; describe: (record: Records[K]) => string;
}) {
  const [open, setOpen] = useState(false), [search, setSearch] = useState(''), [query, setQuery] = useState(''), [offset, setOffset] = useState(0);
  const [page, setPage] = useState<Page<Records[K]>>({ items: [], total: 0 }), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  useEffect(() => {
    if (!open) return;
    let active = true;
    setBusy(true); setError('');
    api.request<Page<Records[K]>>(`/${kind}?limit=25&offset=${offset}&search=${encodeURIComponent(query)}`)
      .then(result => { if (active) setPage(result); })
      .catch((e: Error) => { if (active) setError(e.message); })
      .finally(() => { if (active) setBusy(false); });
    return () => { active = false; };
  }, [open, offset, query, kind, api]);
  return <View style={styles.field}><Text style={styles.label}>{label}</Text>
    <Button title={value || `Choose ${label.toLowerCase()}`} secondary onPress={() => setOpen(true)} />
    {open && <Sheet title={`Choose ${label.toLowerCase()}`} onClose={() => setOpen(false)}>
      <Field label="Search" value={search} onChange={setSearch} autoFocus />
      <Button title="Search records" onPress={() => { setOffset(0); setQuery(search); }} />
      <ErrorText message={error} />{busy && <ActivityIndicator accessibilityLabel="Loading choices" color={colors.teal} />}
      {!busy && !error && page.items.length === 0 && <Empty text={`Create a ${label.toLowerCase()} first.`} />}
      {!busy && !error && page.items.map(row => <View key={row.id} style={{ marginTop: 12 }}><Button title={describe(row)} secondary
        onPress={() => { onChange(row.id, describe(row)); setOpen(false); }} /></View>)}
      <View style={[styles.row, { marginTop: 20 }]}>
        <Button title="Previous" secondary disabled={busy || offset === 0} onPress={() => setOffset(Math.max(0, offset - 25))} />
        <Button title="Next" secondary disabled={busy || offset + 25 >= page.total} onPress={() => setOffset(offset + 25)} />
      </View>
    </Sheet>}
  </View>;
}

/** Parse currency exactly to paise and reject fractional paise, negatives and empty values. */
export function paise(value: string) {
  if (!/^\d{1,7}(\.\d{1,2})?$/.test(value.trim())) throw new Error('Enter a non-negative INR amount with at most two decimal places');
  const [whole, fraction = ''] = value.trim().split('.');
  const result = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
  if (result > 100_000_000) throw new Error('Amount exceeds INR 10,00,000');
  return result;
}

/** Parse whole-number inputs without silently treating blank or malformed input as zero. */
export function integer(value: string) {
  if (!/^-?\d+$/.test(value.trim())) throw new Error('Enter a whole number');
  const result = Number(value);
  if (!Number.isSafeInteger(result)) throw new Error('Number is too large');
  return result;
}

/** Use an ISO date label that the server validates as a real calendar date. */
export function today() { return garageDate(); }
